import re

def transform(x: str) -> str:
    match = re.search(r'\[\[([^]]+)\]\]', x)
    if not match:
        return ""
    content = match.group(1)
    # If there is a pipe, the displayed text is after the last pipe
    if "|" in content:
        return content.split("|")[-1].strip()
    return content.strip()
